  .brand {
    margin-bottom: 0.25rem;
    justify-content: center;
  }

  .sidebar-info {
    display: none; /* Sembunyikan badge status untuk hemat ruang */
  }

  .sidebar-menu {
    display: flex;
    gap: 0.5rem;
    margin-bottom: 0.25rem;
  }

  .menu-btn {
