  }

  .section-title {
    display: none; /* Sembunyikan judul section */
  }

  /* Susun kartu mode berjejer ke samping */
  .mode-cards {
    display: flex;
    flex-direction: row;
    gap: 8px;
    width: 100%;
  }

  .mode-card {
    flex: 1;
    margin: 0;
    padding: 6px 10px !important; /* Ramping: 6px 10px */
    justify-content: center;
    align-items: center;
  }

  /* Sembunyikan deskripsi panjang pada kartu mode di mobile */
  .mode-card p {
    display: none !important;
  }

  .mode-header {
    gap: 0.5rem;
  }

  .mode-icon {
    width: 15px;
    height: 15px;
  }

  .mode-title {
    font-size: 12px !important; /* Ramping: 12px */
